def load_goderik_backstory() -> list[str]:
    text = GODERIK_SHEET.read_text(encoding="utf-8")
    start = text.index("## 1. Предыстория") + len("## 1. Предыстория")
    end = text.index("## 2. Связи")
    block = text[start:end].strip()
    return [paragraph.strip() for paragraph in block.split("\n\n") if paragraph.strip()]


def setup_styles(doc: Document) -> None:
    section = doc.sections[0]
    section.page_width = Inches(8.5)
    section.page_height = Inches(11)
    section.top_margin = Inches(1)
    section.bottom_margin = Inches(1)
    section.left_margin = Inches(1)
    section.right_margin = Inches(1)
    section.header_distance = Inches(0.492)
    section.footer_distance = Inches(0.492)

    styles = doc.styles
    normal = styles["Normal"]
    normal.font.name = "Calibri"
    normal.font.size = Pt(11)
    normal.paragraph_format.space_after = Pt(6)
    normal.paragraph_format.line_spacing = 1.25

    for style_name, size, color, before, after in [
        ("Heading 1", 16, "2E74B5", 18, 10),
        ("Heading 2", 13, "2E74B5", 14, 7),
        ("Heading 3", 12, "1F4D78", 10, 5),
    ]:
        style = styles[style_name]
        style.font.name = "Calibri"
        style.font.size = Pt(size)
        style.font.color.rgb = RGBColor.from_string(color)
        style.paragraph_format.space_before = Pt(before)
        style.paragraph_format.space_after = Pt(after)
        style.paragraph_format.line_spacing = 1.25

    for style_name in ["List Bullet", "List Number"]:
        style = styles[style_name]
        style.font.name = "Calibri"
        style.font.size = Pt(11)
        style.paragraph_format.space_after = Pt(4)
        style.paragraph_format.line_spacing = 1.25


def add_title(doc: Document, text: str, subtitle: str) -> None:
    p = doc.add_paragraph()
    p.paragraph_format.space_after = Pt(3)
    run = p.add_run(text)
    run.font.name = "Calibri"
    run.font.size = Pt(24)
    run.font.color.rgb = RGBColor.from_string("0B2545")
    run.bold = True

    p = doc.add_paragraph()
    p.paragraph_format.space_after = Pt(12)
    run = p.add_run(subtitle)
    run.font.name = "Calibri"
    run.font.size = Pt(11)
    run.italic = True
    run.font.color.rgb = RGBColor.from_string("555555")


def add_bullets(doc: Document, items: list[str]) -> None:
    for item in items:
        # LibreOffice's default list rendering can place the marker too close
        # to Cyrillic text; a leading content space keeps the exported PDF clean.
        doc.add_paragraph(" " + item, style="List Bullet")


def add_labeled_paragraphs(doc: Document, label: str, paragraphs: list[str]) -> None:
    doc.add_heading(label, level=2)
    for paragraph in paragraphs:
        doc.add_paragraph(paragraph)


def add_character(doc: Document, character: dict) -> None:
    doc.add_page_break()
    doc.add_heading(character["name"], level=1)
    role = doc.add_paragraph()
    role.add_run("Роль: ").bold = True
    role.add_run(character["role"])

    add_labeled_paragraphs(doc, "1. Предыстория", character["backstory"])

    doc.add_heading("2. Связи с другими персонажами", level=2)
    add_bullets(doc, character["connections"])

    doc.add_heading("3. Убеждения и характер", level=2)
    for index, belief in enumerate(character["beliefs"], start=1):
        p = doc.add_paragraph()
        p.add_run(f"Убеждение {index}: ").bold = True
        p.add_run(belief)
    p = doc.add_paragraph()
    p.add_run("Характер: ").bold = True
    p.add_run(character["character"])

    doc.add_heading("4. Особенности и ограничения на игру", level=2)
    add_bullets(doc, character["features"])

    doc.add_heading("5. Способности / особые возможности", level=2)
    doc.add_paragraph(character["ability"])

    doc.add_heading("6. Цели по актам", level=2)
    add_bullets(doc, character["goals"])

    doc.add_heading("7. Информация по этапам", level=2)
    add_bullets(doc, character["info"])

    doc.add_heading("Развилки для выбора", level=2)
    add_bullets(doc, character["choices"])


def build() -> None:
    doc = Document()
    setup_styles(doc)
    add_title(
        doc,
        "Содден 1263: черновик персонажных листов v0.2",
        "Рабочий пакет вариантов: 15 игровых персонажей, развернутые предыстории, 3 акта, раскрытие информации и точки выбора для правок.",
    )

    doc.add_heading("Общая схема раскрытия информации", level=1)
    for heading, items in REVEAL_PLAN:
        doc.add_heading(heading, level=2)
        add_bullets(doc, items)

    doc.add_heading("Список листов", level=1)
    for character in CHARACTERS:
        doc.add_paragraph(f"{character['name']} — {character['role']}", style="List Bullet")

    goderik_backstory = load_goderik_backstory()
    for character in CHARACTERS:
        character_sheet = character.copy()
        if character_sheet["name"] == "Годерик ан Крайт":
            character_sheet["backstory"] = goderik_backstory
        elif character_sheet["name"] in EXPANDED_BACKSTORIES:
            character_sheet["backstory"] = EXPANDED_BACKSTORIES[character_sheet["name"]]
        add_character(doc, character_sheet)

    doc.save(OUT)
    print(OUT)


if __name__ == "__main__":
    build()
